// Maps Fonnte's real inbound webhook payload (Gate 6J-C1 verified capture)
// to ADOP's canonical envelope shape (task LOCK A).
//
// senderid is a WhatsApp sender identity/LID, never a message id — never
// used here. inboxid can be 0 or absent, so it is only trusted as a
// providerMessageId when it is a positive integer; otherwise
// providerMessageId is left OFF the envelope entirely so ADOP derives a
// deterministic id server-side (Gate 6J-C1 IDEMPOTENCY LOCK — never an n8n
// execution id or receive-time, which would break on a genuine retry).
//
// text is Fonnte's BUTTON TEXT field, never a plain-message fallback —
// only body.message is the canonical message field.
const body = $input.item.json;

const inboxId = Number(body.inboxid);
const providerMessageId = Number.isInteger(inboxId) && inboxId > 0 ? `fonnte:inbox:${inboxId}` : undefined;

const envelope = {
  provider: 'fonnte',
  channel: 'whatsapp',
  senderAddress: String(body.sender || body.from || ''),
  receiverAddress: String(body.device || ''),
  messageText: String(body.message || ''),
  providerTimestamp: String(body.timestamp || ''),
};
if (providerMessageId) {
  envelope.providerMessageId = providerMessageId;
}

return [{ json: { envelope, canonicalBody: JSON.stringify(envelope) } }];

// HMAC over timestamp + the EXACT canonical body string this same
// execution will POST (see Post ADOP Inbound's jsonBody, which references
// $json.canonicalBody verbatim — never a re-serialized copy). The secret
// comes ONLY from the n8n credential/environment, never hardcoded (task
// LOCK B).
//
// NOTE: this requires the n8n instance to allow the 'crypto' Node.js
// builtin inside Code nodes (self-hosted: NODE_FUNCTION_ALLOW_BUILTIN=crypto
// or equivalent). If that is not configured, this node throws and the
// workflow fails closed — it does NOT fall back to calling ADOP unsigned,
// since ADOP's own endpoint rejects any request without a valid signature
// regardless (see src/lib/assistant-inbound/signature.ts). This is a known
// deployment-time dependency, unverified against the actual hosted n8n
// runtime as of this gate — see README §Deployment Notes / LIMITATIONS.
const crypto = require('crypto');

const secret = $env.ADOP_ASSISTANT_INBOUND_SIGNING_SECRET;
if (!secret) {
  throw new Error('ADOP_ASSISTANT_INBOUND_SIGNING_SECRET is not configured for this n8n environment.');
}

const timestamp = String(Math.floor(Date.now() / 1000));
const canonicalBody = $json.canonicalBody;
const signature = crypto.createHmac('sha256', secret).update(`${timestamp}.${canonicalBody}`).digest('hex');

return [{ json: { ...$json, timestamp, signature } }];

// Closed allowlist — MUST mirror src/lib/assistant-inbound/safe-replies.ts
// exactly (task LOCK H: only allowlisted static templates keyed by
// safeReplyCode, never a raw error or messageText). Update both places
// together if the reply vocabulary ever changes.
const TEMPLATES = {
  paired: 'Nomor WhatsApp berhasil dipasangkan.',
  verified: 'Nomor WhatsApp Anda berhasil diverifikasi.',
  invalid_or_expired: 'Kode tidak valid atau sudah kedaluwarsa. Silakan minta kode baru.',
  locked: 'Terlalu banyak percobaan salah. Silakan minta kode baru dari admin.',
  ambiguous: 'Permintaan tidak dapat diproses saat ini. Silakan hubungi admin.',
  duplicate: 'Permintaan ini sudah diproses sebelumnya.',
  rate_limited: 'Terlalu banyak permintaan. Silakan coba lagi beberapa saat lagi.',
};

const code = $json.reply && $json.reply.safeReplyCode;
const replyText = TEMPLATES[code] || '';

return [{ json: { ...$json, replyText } }];
